export const code = async ({ diagnosis: d, context: c }) => {
  if (!d || d.sku_code !== c.sku_code || !Array.isArray(d.listings) || d.listings.length !== c.listings.length) throw new Error('Attribute diagnosis SKU/Listing coverage mismatch');
  const ids = new Set();
  for (const result of d.listings) {
    const l = c.listings.find(l => l.sku_product_id === result.sku_product_id);
    if (!l || ids.has(l.sku_product_id)) throw new Error('Unknown or duplicate Listing in attribute diagnosis');
    ids.add(l.sku_product_id);
    if (!['KEEP', 'CHANGE', 'insufficient_data'].includes(result.assessment) || !Array.isArray(result.problems) || !Array.isArray(result.actions) || !Array.isArray(result.limitations)) throw new Error('Invalid attribute assessment');
    const issues = new Set();
    for (const p of result.problems) {
      const a = l.attributes.find(a => a.id === p.attribute_id && a.complex_id === (p.complex_id ?? 0));
      if (!a || [9048, 12141, 22390, 4180, 4191, 11254].includes(a.id)) throw new Error('Unknown or exempt attribute reported as a problem');
      if (!p.id || issues.has(p.id) || !['P0', 'P1'].includes(p.priority) || p.confidence !== 'high' || !p.fact_evidence || !p.impact || !p.recommendation) throw new Error('Attribute issue lacks high confidence or evidence');
      const current = JSON.stringify(a.current_values);
      if (!(p.current_evidence === '__EMPTY__' ? a.current_values.length === 0 : p.current_evidence && current.includes(p.current_evidence))) throw new Error('Attribute evidence is not from the current Listing');
      issues.add(p.id);
    }
    const actionKeys = new Set();
    for (const action of result.actions) {
      const a = l.attributes.find(a => a.id === action.attribute_id && a.complex_id === (action.complex_id ?? 0));
      const key = `${action.attribute_id}:${action.complex_id ?? 0}`;
      if (!a || actionKeys.has(key) || !issues.has(action.problem_id) || !Array.isArray(action.suggested_values)) throw new Error('Invalid or duplicate attribute action');
      actionKeys.add(key);
      if (a.max_count && action.suggested_values.length > a.max_count) throw new Error(`Attribute ${a.id} exceeds official max_count`);
      if (new Set(action.suggested_values.map(v => `${v.id}:${v.value}`)).size !== action.suggested_values.length) throw new Error('Duplicate suggested values');
      for (const v of action.suggested_values) {
        if (typeof v.value !== 'string' || !v.value.trim()) throw new Error('Empty attribute value');
        if (a.input_mode === 'unknown') throw new Error('Cannot modify an attribute without its official definition');
        if (a.input_mode === 'dictionary' && !a.options.some(o => o.id === v.id && o.value === v.value)) throw new Error(`Attribute ${a.id}: value is outside the official options pool`);
      }
    }
    if (result.assessment === 'KEEP' && (result.problems.length || result.actions.length)) throw new Error('KEEP conflicts with attribute changes');
    if (result.assessment === 'CHANGE' && (!result.problems.length || !result.actions.length)) throw new Error('CHANGE requires evidence and actions');
  }
  return d;
};

export const code = async ({ context, policy, attributes, prompts }) => {
  const listings = context.listings.map(l => ({ sku_product_id: l.sku_product_id, store_name: l.store_name,
    product_info: l.product_info, title: l.title, description: l.description,
    rich_content_text: l.rich_content_text, rich_content_configured: l.rich_content_configured,
    primary_image_url: l.primary_image_url, search_terms: l.search_terms,
    attributes: l.attributes.map(a => ({ id: a.id, name: a.name, current_values: a.current_values })) }));
  return { prompt: prompts.rule + '\n\n' + prompts.text_contract,
    text: JSON.stringify({ sku_code: context.sku_code, grade: context.grade, stage: context.stage, as_of: context.as_of, policy, attribute_diagnosis: attributes, listings }),
    files: listings.filter(l => l.primary_image_url).map(l => ({ file: l.primary_image_url })) };
};

export const code = async ({ diagnosis: d, context: c, policy }) => {
  if (!d || d.sku_code !== c.sku_code || !Array.isArray(d.listings) || d.listings.length !== c.listings.length) throw new Error('Text diagnosis SKU/Listing coverage mismatch');
  const ids = new Set();
  for (const r of d.listings) {
    const l = c.listings.find(l => l.sku_product_id === r.sku_product_id);
    const p = policy.listings.find(p => p.sku_product_id === r.sku_product_id);
    if (!l || ids.has(l.sku_product_id) || !Array.isArray(r.problems) || !Array.isArray(r.limitations)) throw new Error('Invalid text Listing coverage');
    ids.add(l.sku_product_id);
    const issueIds = new Set();
    for (const issue of r.problems) {
      if (!issue.id || issueIds.has(issue.id) || !['title', 'description', 'rich_content', 'seo'].includes(issue.module) || !['P0', 'P1'].includes(issue.priority) || issue.confidence !== 'high' || !issue.fact_evidence || !issue.impact || !issue.recommendation) throw new Error('Text issue lacks high confidence or evidence');
      const source = issue.module === 'seo' ? JSON.stringify(l.search_terms) : issue.module === 'rich_content' ? l.rich_content_text : l[issue.module];
      if (!(issue.current_evidence === '__EMPTY__' ? !source : issue.current_evidence && source.includes(issue.current_evidence))) throw new Error('Text evidence is not from this Listing/module');
      issueIds.add(issue.id);
    }
    for (const module of ['title', 'description', 'rich_content']) {
      const m = r[module];
      if (!m || !['pass', 'fail', 'insufficient_data', 'not_configured'].includes(m.quality) || !['KEEP', 'REWRITE'].includes(m.action) || !m.reason) throw new Error(`Invalid ${module} assessment`);
      const issues = r.problems.filter(i => i.module === module);
      if (m.action === 'REWRITE') {
        if (!issues.length || !m.recommended_ru || !m.recommended_zh) throw new Error('Rewrite needs evidence and complete Russian/Chinese copy');
        if (m.quality === 'pass' && p.text_strategy === 'pass_then_keep') throw new Error('Passing B/C/CLR text must KEEP');
      }
      if (m.quality === 'fail' && m.action !== 'REWRITE') throw new Error('Failed text needs a complete rewrite');
      if (m.quality === 'insufficient_data' && (m.action !== 'KEEP' || issues.length)) throw new Error('Missing evidence cannot become a modification task');
    }
    if (!l.rich_content_configured && (r.rich_content.quality !== 'not_configured' || r.rich_content.action !== 'KEEP')) throw new Error('Unconfigured rich content must KEEP');
    if (!r.funnel_attribution?.explanation || typeof r.funnel_attribution.listing_explains_anomaly !== 'boolean') throw new Error('Missing funnel attribution');
    if (r.funnel_attribution.listing_explains_anomaly && (!p.funnel_anomaly || !r.problems.length)) throw new Error('Unsupported funnel attribution');
    if (!r.seo || !['verified_irrelevant', 'no_verified_irrelevant', 'insufficient_data'].includes(r.seo.traffic_quality) || !Array.isArray(r.seo.verified_terms)) throw new Error('Invalid SEO assessment');
    if (!l.search_terms.length && r.seo.traffic_quality !== 'insufficient_data') throw new Error('No terms means SEO evidence is unavailable');
    r.seo.verified_terms = r.seo.verified_terms.map(term => typeof term === 'string' ? term : term?.query);
    for (const term of r.seo.verified_terms) if (typeof term !== 'string' || !l.search_terms.some(t => t.query === term)) throw new Error('SEO term absent from source');
    if (r.seo.traffic_quality === 'verified_irrelevant' && (!r.seo.verified_terms.length || !r.problems.some(i => i.module === 'seo'))) throw new Error('Irrelevant SEO traffic needs a verified issue');
    if (!Array.isArray(r.top_issues) || !r.summary) throw new Error('Missing executive summary');
  }
  return d;
};

export const code = async ({ context: c, policy, attributes, text, config }) => {
  const listings = c.listings.map(l => {
    const a = attributes.listings.find(a => a.sku_product_id === l.sku_product_id);
    const t = text.listings.find(t => t.sku_product_id === l.sku_product_id);
    const p = policy.listings.find(p => p.sku_product_id === l.sku_product_id);
    const problems = a.problems.concat(t.problems).sort((a, b) => a.priority.localeCompare(b.priority));
    const p0 = problems.filter(p => p.priority === 'P0').length, p1 = problems.filter(p => p.priority === 'P1').length;
    const incomplete = a.assessment === 'insufficient_data' || [t.title, t.description].some(m => m.quality === 'insufficient_data');
    const status = p0 ? 'has_error' : p1 ? 'needs_optimization' : incomplete ? null : 'healthy';
    const limitations = [...new Set(p.warnings.concat(a.limitations, t.limitations))];
    return { sku_product_id: l.sku_product_id, store_name: l.store_name, product_id: l.product_id,
      status, audit_status: incomplete ? 'insufficient_data' : limitations.length ? 'partial' : 'complete',
      p0_count: p0, p1_count: p1, attribute_change_count: a.actions.length,
      title_action: t.title.action, description_action: t.description.action, rich_content_action: t.rich_content.action,
      funnel_anomaly: p.funnel_anomaly, seo_traffic_quality: t.seo.traffic_quality,
      summary: [a.summary, t.summary].filter(Boolean).join('\n'),
      top_issues: problems.length ? problems.slice(0, 3).map(p => `${p.priority}：${p.recommendation}`) : t.top_issues,
      problems, attribute_actions: a.actions.map(action => ({ ...action, current_values: l.attributes.find(a => a.id === action.attribute_id && a.complex_id === (action.complex_id ?? 0))?.current_values ?? [] })),
      title: t.title, description: t.description, rich_content: t.rich_content,
      funnel_attribution: t.funnel_attribution, seo: t.seo, limitations,
      latest_complete_funnel: p.latest_complete_period, current_partial_funnel: p.current_partial_period,
      source_timestamps: { product: l.product_synced_at, attributes: l.attributes_synced_at } };
  });
  const sum = k => listings.reduce((n, l) => n + l[k], 0);
  const status = sum('p0_count') ? 'has_error' : sum('p1_count') ? 'needs_optimization' : listings.some(l => !l.status) ? null : 'healthy';
  const metrics = { sku_code: c.sku_code, grade: c.grade, stage: c.stage, status,
    audit_status: listings.some(l => l.audit_status === 'insufficient_data') ? 'insufficient_data' : listings.some(l => l.audit_status === 'partial') ? 'partial' : 'complete',
    listing_count: listings.length, p0_count: sum('p0_count'), p1_count: sum('p1_count'),
    attribute_change_count: sum('attribute_change_count'), title_rewrite_count: listings.filter(l => l.title_action === 'REWRITE').length,
    description_rewrite_count: listings.filter(l => l.description_action === 'REWRITE').length,
    rich_content_rewrite_count: listings.filter(l => l.rich_content_action === 'REWRITE').length,
    funnel_anomaly_count: policy.funnel_anomaly_count, verified_irrelevant_term_count: listings.reduce((n, l) => n + l.seo.verified_terms.length, 0) };
  const lines = [`# Ozon Listing诊断：${c.sku_code}`, `规则：${config.rule_version}；Grade/Stage：${c.grade}/${c.stage}；日期：${c.as_of}（${c.time_zone}）`, `总状态：${status ?? 'insufficient_data'}；P0：${metrics.p0_count}；P1：${metrics.p1_count}`];
  for (const l of listings) {
    lines.push(`\n## ${l.store_name}（Listing ${l.sku_product_id}）`, l.summary, `Title: ${l.title_action}；Description: ${l.description_action}；Rich-content: ${l.rich_content_action}`, l.funnel_attribution.explanation, `SEO：${l.seo.traffic_quality} — ${l.seo.explanation}`);
    for (const p of l.problems) lines.push(`\n- **${p.priority} / ${p.defect_type}**：${p.current_evidence}\n  依据：${p.fact_evidence}\n  影响：${p.impact}\n  建议：${p.recommendation}`);
    if (!l.problems.length) lines.push('No significant Listing issue found.');
    if (!l.attribute_actions.length) lines.push('Attributes: KEEP');
    if (l.attribute_actions.length) {
      const cell = v => String(v).replace(/\|/g, '\\|').replace(/\n/g, '<br>');
      lines.push('\n| 店铺 | 属性 | 当前值 | 建议最终值 | 理由 |', '| --- | --- | --- | --- | --- |');
      for (const a of l.attribute_actions) lines.push(`| ${cell(l.store_name)} | ${cell(a.attribute_name ?? a.attribute_id)} | ${cell(a.current_values.map(v => v.value).join('、'))} | ${cell(a.suggested_values.map(v => v.value).join('、'))} | ${cell(a.reason)} |`);
    }
    for (const k of ['title', 'description', 'rich_content']) if (l[k].action === 'REWRITE') lines.push(`\n### ${k}\n${l[k].recommended_ru}\n\n中文：${l[k].recommended_zh}`);
    lines.push('\n### 最小动作清单');
    if (!l.problems.length) lines.push('No action required.');
    for (const p of l.problems) lines.push(`- ${p.priority}：${p.recommendation}`);
    if (l.limitations.length) lines.push(`\n数据限制：${l.limitations.join('；')}`);
  }
  return { metrics, listings, markdown: lines.join('\n'), llm: { provider: config.ai_provider, model: config.model, action: 'extractStructuredData' }, rule_version: config.rule_version, as_of: c.as_of, time_zone: c.time_zone };
};
